        return Ok(());
    }
    let mise_bin = mise_bin_for_shims().absolutize()?.into_owned();
    let shims = wrappers
        .keys()
        .flat_map(|name| platform_shim_names(&mise_bin, name))
        .collect();
    if let Some(error) = write_bootstrap_shims(&mise_bin, &dirs::COMMAND_WRAPPERS, &shims)? {
        return Err(error);
    }
    Ok(())
}

